/// (`register` without the proof, then `storePqzPop`, F22's restart-safe flow) when the one transaction's gas is above half
/// the chain's block gas limit or its regular gas above the per-transaction cap; each step's gas and the total.
class RegistrationGas {
  /// 1 or 2
  final int transactions;

  /// the steps prepared, in the order they land (after a restart between the two, the second alone)
  final List<StepGas> steps;

  /// the steps' gas added; `None` when a step's is not known
  final BigInt? totalGas;

  const RegistrationGas({
    required this.transactions,
    required this.steps,
    this.totalGas,
  });

  @override
  int get hashCode =>
      transactions.hashCode ^ steps.hashCode ^ totalGas.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is RegistrationGas &&
          runtimeType == other.runtimeType &&
          transactions == other.transactions &&
          steps == other.steps &&
          totalGas == other.totalGas;
}

/// A registration as the registry holds it (`registration_of`).
class RegistrationState {
  final bool registered;

  /// the hash commit of the KEM key (`attrs.kemPkHash`, `0x` + 64 hex; all zero: none)
  final String kemPkHash;

  /// the KEM key of version 0 is stored (a commit filled, or the full key given at `register`)
  final bool kemStored;

  /// the PQZ key of version 0 has its proof stored (`pqzPopOf`; owner 2026-11-19, S2)
  final bool pqzPopStored;

  /// and a PoP verifier checked it (`pqzKeyAt(…).proven`; false on a chain with none)
  final bool pqzProven;

  const RegistrationState({
    required this.registered,
    required this.kemPkHash,
    required this.kemStored,
    required this.pqzPopStored,
    required this.pqzProven,
  });

  static Future<RegistrationState> default_() =>
      ScaasSdk.instance.api.scaasSdkAccountRegistrationStateDefault();

  @override
  int get hashCode =>
      registered.hashCode ^
      kemPkHash.hashCode ^
      kemStored.hashCode ^
      pqzPopStored.hashCode ^
      pqzProven.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is RegistrationState &&
          runtimeType == other.runtimeType &&
          registered == other.registered &&
          kemPkHash == other.kemPkHash &&
          kemStored == other.kemStored &&
          pqzPopStored == other.pqzPopStored &&
          pqzProven == other.pqzProven;
}

/// `restore`: seed `seed` on chain `chain` (a profile key): the UA keys `kinds` of wallet `account`, `gap` (at most 1024, the
/// usual 20) past the last registered index.
class Restore {
  final String seed;
  final String chain;
  final Uint16List kinds;
  final int account;
  final int gap;

  const Restore({
    required this.seed,
    required this.chain,
    required this.kinds,
    required this.account,
    required this.gap,
  });

  @override
  int get hashCode =>
      seed.hashCode ^
      chain.hashCode ^
      kinds.hashCode ^
      account.hashCode ^
      gap.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is Restore &&
          runtimeType == other.runtimeType &&
          seed == other.seed &&
          chain == other.chain &&
          kinds == other.kinds &&
          account == other.account &&
          gap == other.gap;
}

/// One step of a registration carrying its PQZ key's proof as quoted at prepare (owner 2026-11-20).
class StepGas {
  /// `register` (or `registerWebAuthn`, `registerMsig`), with or without the proof, or `storePqzPop`
  final String entry;

  /// the step's gas limit: max(the node's estimate, the gas table's figure), the table's with the intrinsic cost, the
  /// calldata and the margin; `None` where neither is known yet (a later step is not estimated before the one before it
  /// landed)
  final BigInt? gas;

  /// the bound of its regular part (EIP-8037): the table's; the estimate, whole, where the table has no row
  final BigInt? regularGas;

  const StepGas({required this.entry, this.gas, this.regularGas});

  @override
  int get hashCode => entry.hashCode ^ gas.hashCode ^ regularGas.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is StepGas &&
          runtimeType == other.runtimeType &&
          entry == other.entry &&
          gas == other.gas &&
          regularGas == other.regularGas;
}

/// A `registerWebAuthn` key, named.
class WebAuthnArgs {
  final String x;
  final String y;
  final String rpIdHash;

  const WebAuthnArgs({
    required this.x,
    required this.y,
    required this.rpIdHash,
  });

  @override
  int get hashCode => x.hashCode ^ y.hashCode ^ rpIdHash.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is WebAuthnArgs &&
          runtimeType == other.runtimeType &&
          x == other.x &&
          y == other.y &&
          rpIdHash == other.rpIdHash;
}
